'use strict';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dt=v=>v?new Date(v).toLocaleDateString('it-IT',{day:'2-digit',month:'short',year:'numeric'}):'Data non disponibile';
const money=v=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(v||0);
const kinds={request:'Richiesta esplicita',signal:'Segnale aziendale',measurement:'Misura tecnica',fact:'Fatto verificato',limitation:'Limite del controllo',hypothesis:'Ipotesi'};
let S=null,view='overview',filters={},current=null,tab='summary',timer,stageSaving=false;
const toastElement=$('#toast');
let pollBusy=false, detailOpener=null, detailSequence=0, archiveRows=[], archiveSearch='', archiveOffset=0;
function toast(message){
 const el=toastElement,host=document.querySelector('dialog[open]')||document.body;
 host.append(el);el.textContent=message;el.classList.add('show');clearTimeout(timer);
 timer=setTimeout(()=>el.classList.remove('show'),6000);
}
function navigate(destination){
 detailSequence++;view=destination;filters={};render();window.scrollTo({top:0,behavior:'instant'});
 $('#main')?.focus({preventScroll:true});
}
function connectionStatus(offline=false){
 const el=$('.live');if(!el)return;
 el.classList.toggle('offline',offline);el.classList.toggle('is-running',!offline&&Boolean(S?.job.running));
 el.textContent=offline?'Connessione interrotta · nuovo tentativo in corso':S?.job.running?'Ricerca in corso':'Dati salvati in locale';
}
function showDetail(){const d=$('#detail');if(!d.open)d.showModal();d.scrollTop=0;}
for(const id of ['detail','research'])document.querySelector('#'+id)?.addEventListener('close',()=>{
 document.body.append(toastElement);detailSequence++;
 if(id==='detail'&&detailOpener){
  const {kind,value}=detailOpener;
  const target=[...document.querySelectorAll('['+kind+']')].find(el=>el.getAttribute(kind)===value);
  target?.focus({preventScroll:true});detailOpener=null;
 }
});
async function api(path,body){const r=await fetch('/api'+path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':S.csrf},body:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw new Error(data.error||'Operazione non riuscita');return data}
function link(url,label){try{const u=new URL(url,location.origin);if(!['http:','https:'].includes(u.protocol))return esc(label)}catch{return esc(label)}return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label||url)} ↗</a>`}
const badge=e=>`<span class="engine-dot engine-${esc(e)}">${esc(e)}</span>`;
function nav(id,label,icon,count){return `<button class="navitem ${view===id?'active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon||''}<span>${label}</span>${count!==undefined?`<span class="count">${count}</span>`:''}</button>`}
function icon(name){const paths={grants:'M3 10h18 M4 10V7l8-4 8 4v3 M6 10v8 M12 10v8 M18 10v8 M3 21h18 M3 18h18',evidence:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h5',contacts:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M16 3.13a4 4 0 0 1 0 7.75',overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',all:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',pipeline:'M4 4v16 M12 4v16 M20 4v16 M2 7h4 M10 12h4 M18 16h4',results:'M4 3v17h17 M8 15l4-5 4 2 5-7',activity:'M5 5h15 M5 12h15 M5 19h15 M2 5h.01 M2 12h.01 M2 19h.01',archive:'M3 3h18v5H3z M5 8v13h14V8 M9 12h6',settings:'M4 6h16 M4 12h16 M4 18h16 M8 4v4 M16 10v4 M10 16v4'};return `<svg class="nav-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.all}"/></svg>`}
const engineNames={A:'Richieste di siti',B:'Agenzie e collaborazioni',C:'Attività in crescita',D:'Problemi del sito',E:'Segnali combinati'};
const groupLabels={agencies:'Aziende · agenzie e partner',direct:'Privati · clienti diretti'};
function activeContacts(){return S.items.filter(i=>!i.dismissed_at&&!['lost','discarded'].includes(i.stage))}
function groupCount(group){return activeContacts().filter(i=>!group||i.contact_group===group).length}
function resultTabs(){return `<nav class="result-tabs" aria-label="Categorie dei risultati">${[['all','Tutti','Tutti i contatti'],['agencies','Aziende','Agenzie e partner'],['direct','Privati','Negozi, artigiani e professionisti']].map(([id,label,desc])=>`<button data-view="${id}" class="${(view===id||(id==='all'&&view==='overview'))?'active':''}" ${(view===id||(id==='all'&&view==='overview'))?'aria-current="page"':''}><strong>${label} <span class="count">${groupCount(id==='all'?null:id)}</span></strong><span>${desc}</span></button>`).join('')}</nav>`}
function primaryEvidence(i){return i.evidence.find(e=>e.kind==='request')||i.evidence.find(e=>e.kind==='signal')||i.evidence.find(e=>e.kind==='measurement')||i.evidence[0]}
function isContacted(i){return Boolean(i.contacted_at||i.prior_contacted||['contacted','replied','proposal','won'].includes(i.stage))}
function contactControl(i){if(i.dismissed_at)return `<span class="muted small">Eliminata il ${dt(i.dismissed_at)}</span>`;return isContacted(i)?`<span class="contact-status">✓ Contatto confermato${i.contacted_at?' · '+dt(i.contacted_at):''}</span>`:`<button class="confirm-contact" data-action="confirm-contact" data-id="${i.id}" ${stageSaving?'disabled':''}>Conferma contatto</button>`}
function dismissalControl(i){return `<button class="${i.dismissed_at?'':'danger quiet'}" data-action="${i.dismissed_at?'restore-proposal':'dismiss-proposal'}" data-id="${i.id}" ${stageSaving?'disabled':''} title="${i.dismissed_at?'Riammetti questa azienda nelle ricerche':'Rimuovi la proposta ed escludi questo sito dalle ricerche future'}">${i.dismissed_at?'Ripristina proposta':'Elimina proposta'}</button>`}
function nextStep(i){if(isContacted(i))return 'Aggiorna la trattativa quando ricevi una risposta.';if(i.target_exclusion||i.do_not_contact)return 'Non contattare questa azienda.';if(i.prior_contacted)return 'Controlla lo storico prima di ricontattarla.';if(!i.latest_date)return i.explicit?'Verifica che la richiesta sia ancora attuale.':'Verifica quando è stato pubblicato il segnale.';return i.explicit?'Confronta i requisiti con le tue competenze.':'Conferma se c’è un progetto web da discutere.'}
function mainNav(){
 const section=['overview','all','agencies','direct','activity'].includes(view)?'overview':['pipeline','legacy','results','archive'].includes(view)?'pipeline':view==='grants'?'grants':'settings';
 return [['overview','Ricerca','all'],['pipeline','Contatti','contacts'],['grants','Bandi','grants'],['settings','Impostazioni','settings']].map(([id,label,symbol])=>`<button class="navitem ${section===id?'active':''}" data-view="${id}" ${section===id?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span></button>`).join('');
}
function contactTabs(){return `<nav class="workspace-tabs" aria-label="Viste dei contatti">${[['pipeline','Bacheca'],['legacy','Elenco'],['results','Statistiche']].map(([id,label])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`}
function render(){if(!S)return;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><i>c</i>CustomerSearch<small>Trova nuovi clienti</small></div><nav class="navgroup" aria-label="Principale">${mainNav()}</nav><div class="sidebar-footer"><span class="avatar">DP</span> Diego Pavanello<div class="spacer"></div><span>Padova · il tuo spazio di lavoro</span></div></aside><div class="workspace"><header class="topbar"><span>${esc(viewName())}</span><div class="live ${S.job.running?'is-running':''}" role="status">${S.job.running?'Ricerca in corso':'Dati salvati in locale'}</div></header><main class="main" id="main" tabindex="-1"></main></div></div>`;renderMain()}

function viewName(){return ({grants:'Bandi',overview:'Ricerca',all:'Ricerca',agencies:'Ricerca · Aziende',direct:'Ricerca · Privati',pipeline:'Contatti · Bacheca',results:'Contatti · Statistiche',activity:'Ricerche e fonti',archive:'Archivio',settings:'Impostazioni'})[view]||engineNames[view]||view}
function header(title,desc){return `<div class="heading"><div><h1>${title}</h1><p>${desc}</p></div><button class="primary" data-action="research">＋ Cerca clienti</button></div>${S.job.running?`<div class="job"><div><p>${esc(S.job.message)}</p><span class="small muted">${S.job.checked} controlli · ${S.job.added} nuove schede · nessuna scadenza globale</span></div><button data-action="stop">Interrompi</button></div>`:''}`}
function card(i,compact=false){const ev=primaryEvidence(i);return `<article class="card ${isContacted(i)?'contacted-card':''}" data-card-id="${i.id}" ${compact?'draggable="true"':''}>${compact?`<div class="drag-grip" aria-hidden="true">⠿ Trascina per spostare</div>`:''}<div class="card-top"><div class="company"><h3>${esc(i.name)}</h3>${link(i.website,i.domain)}</div><div class="score" title="Priorità di valutazione, non probabilità di vendita">${i.score}<span>/100</span><small>Priorità</small></div></div><div class="tags"><span class="tag contact-kind" title="${esc(i.contact_group_basis)}">${esc(groupLabels[i.contact_group])}</span><span class="tag ${ev?.kind||'fact'}">${kinds[ev?.kind]||'Riscontro'}</span><span class="tag">${esc(S.stages[i.stage])}</span>${i.qualification_label?`<span class="tag limitation">${esc(i.qualification_label)}</span>`:''}${!i.latest_date?'<span class="tag limitation">Data da verificare</span>':''}${i.prior_contacted?'<span class="tag limitation">Già contattata</span>':''}${i.do_not_contact?'<span class="tag limitation">Non contattare</span>':''}</div>${!compact&&(i.matched_engines||[]).length>1?`<div class="source-meta">Riscontri riuniti: ${i.matched_engines.map(k=>esc(engineNames[k])).join(' · ')}</div>`:''}<div class="card-main"><p class="reason"><strong>Perché te la propongo</strong>${esc(i.reason)}</p>${compact?'':`<div class="card-guide"><div><strong>Servizio da proporre</strong><p>${esc(i.service)}</p></div><div><strong>Prossimo passo</strong><p>${esc(nextStep(i))}</p></div></div>`}</div><div class="cardfooter"><div class="source-meta">${ev?link(ev.url,'Leggi la fonte originale'):''}<br>${ev?.published_at?'Pubblicata il '+dt(ev.published_at):'Data della fonte non disponibile'}${compact?'':` · ${esc(i.location||'Località da verificare')}`}</div><div class="card-actions">${contactControl(i)}<button data-open="${i.id}">Apri scheda →</button>${dismissalControl(i)}</div></div>${compact?`<label class="move-control">Sposta in<select data-move-id="${i.id}" aria-label="Sposta ${esc(i.name)}" ${stageSaving?'disabled':''}>${options(Object.entries(S.stages),i.stage,'Scegli stato')}</select></label>`:''}</article>`}
function empty(title='Nessuna opportunità in questa vista',desc='Avvia i motori o modifica i filtri. Una pagina entra qui solo quando la fonte contiene un riscontro pertinente.'){return `<div class="empty"><h2>${title}</h2><p>${desc}</p><button data-action="research">Avvia una ricerca</button></div>`}
function metrics(){const live=S.items.filter(i=>!i.dismissed_at&&!['lost','discarded'].includes(i.stage));const distinct=items=>new Set(items.map(i=>i.company_id)).size;const values=view==='results'?[['Contatti registrati',S.stats.engines.reduce((n,e)=>n+e.contacted,0),'Invii annotati nelle schede'],['Risposte ricevute',S.stats.engines.reduce((n,e)=>n+e.replied,0),'Esiti che hai registrato'],['Incassi registrati',money(S.stats.engines.reduce((n,e)=>n+e.revenue,0)),'Importi effettivi, nessuna stima']]:[['Aziende raccolte',distinct(live),'Nella raccolta attiva'],['Con richieste esplicite',distinct(live.filter(i=>i.explicit)),'Da verificare nelle fonti'],['Pronte al contatto',distinct(live.filter(i=>i.stage==='ready'&&!i.do_not_contact)),'Segnate da te come pronte']];return `<div class="metrics">${values.map(v=>`<div class="metric"><div class="caption">${v[0]}</div><div class="number">${v[1]}</div><div class="caption">${v[2]}</div></div>`).join('')}</div>`}
function options(values,selected,placeholder){return `<option value="">${placeholder}</option>`+values.map(v=>{const [k,t]=Array.isArray(v)?v:[v,v];return `<option value="${esc(k)}" ${String(k)===String(selected)?'selected':''}>${esc(t)}</option>`}).join('')}
function filterUI(){const vals=k=>[...new Set(S.items.map(i=>i[k]).filter(Boolean))].sort();return `<div class="filter-box"><div class="filters"><label>Cerca un contatto<input id="filter-search" data-filter="search" placeholder="Nome, sito o parola chiave" value="${esc(filters.search||'')}"></label><label>Tipo di opportunità<select data-filter="engine">${options(Object.entries(engineNames),filters.engine,'Tutti i tipi')}</select></label><label>Stato<select data-filter="stage">${options([...Object.entries(S.stages),['deleted','Eliminate da me']],filters.stage,'Schede attive')}</select></label><label>Data della fonte<select data-filter="days">${options([['30','Ultimi 30 giorni'],['90','Ultimi 90 giorni'],['unknown','Senza data']],filters.days,'Qualsiasi data')}</select></label></div><details><summary>Filtra anche per settore, località e servizio</summary><div class="filters more"><label>Settore<select data-filter="sector">${options(vals('sector'),filters.sector,'Tutti i settori')}</select></label><label>Località<input data-filter="location" placeholder="Città o regione" value="${esc(filters.location||'')}"></label><label>Servizio<select data-filter="service">${options(vals('service'),filters.service,'Tutti i servizi')}</select></label><label>Priorità minima (0–100)<input type="number" min="0" max="100" data-filter="score" placeholder="Qualsiasi" value="${esc(filters.score||'')}"></label></div></details></div>`}
function filtered(){return S.items.filter(i=>{if(['agencies','direct'].includes(view)&&i.contact_group!==view)return false;if(filters.stage==='deleted'){if(!i.dismissed_at)return false}else if(i.dismissed_at)return false;if(!filters.stage&&['discarded','lost'].includes(i.stage))return false;if(S.engines[view]&&!(i.matched_engines||[i.engine]).includes(view))return false;if(filters.engine&&!(i.matched_engines||[i.engine]).includes(filters.engine))return false;if(filters.stage&&filters.stage!=='deleted'&&i.stage!==filters.stage)return false;if(filters.sector&&i.sector!==filters.sector)return false;if(filters.service&&i.service!==filters.service)return false;if(filters.location&&!(i.location||'').toLowerCase().includes(filters.location.toLowerCase()))return false;if(filters.score&&i.score<Number(filters.score))return false;if(filters.search&&![i.name,i.domain,i.reason].join(' ').toLowerCase().includes(filters.search.toLowerCase()))return false;if(filters.days==='unknown'&&i.latest_date)return false;if(filters.days&&filters.days!=='unknown'&&(!i.latest_date||(Date.now()-new Date(i.latest_date).getTime())/864e5>Number(filters.days)))return false;return true})}
function technicalSuggestions(){const items=S.items.filter(i=>!i.dismissed_at&&!i.target_exclusion&&!i.qualification_rejected&&!i.do_not_contact&&!i.prior_contacted&&['review','ready'].includes(i.stage)&&!i.explicit&&i.score<S.settings.min_priority&&(i.matched_engines||[i.engine]).includes('D')).slice(0,5);return items.length?`<section class="technical-suggestions"><div class="sectionhead"><h2>Altri siti con problemi misurati</h2><button class="quiet" data-view="D">Tutti i controlli →</button></div><p class="small muted">Verifiche tecniche da valutare: queste aziende non hanno dichiarato una richiesta di lavoro. I punteggi e le fonti sono nelle schede.</p><div class="cards">${items.map(i=>card(i)).join('')}</div></section>`:''}
function renderMain(){const m=$('#main');if(view==='overview'){const top=[...new Map(S.items.filter(i=>!i.dismissed_at&&!['lost','discarded','won'].includes(i.stage)&&!i.target_exclusion&&!i.qualification_rejected&&!i.do_not_contact&&!i.prior_contacted&&i.score>=S.settings.min_priority).reverse().map(i=>[i.company_id,i])).values()].sort((a,b)=>b.score-a.score).slice(0,10);m.innerHTML=header('I contatti da valutare','Controlla perché sono state selezionate e apri una scheda per decidere il prossimo passo.')+resultTabs()+metrics()+`<div class="sectionhead"><h2>Da guardare per prime</h2><button class="quiet" data-view="all">Vedi tutti i contatti →</button></div><p class="small muted">Fino a 10 aziende con priorità da ${S.settings.min_priority}/100. Quelle già contattate sono in verde.</p>`+(top.length?`<div class="cards">${top.map(i=>card(i)).join('')}</div>`:empty('Nessuna azienda in evidenza','Avvia una ricerca o apri la raccolta completa per valutare anche le altre aziende.'))+technicalSuggestions()+`<details class="helper"><summary>Come usare questa raccolta</summary><div class="panel steps"><p>Apri una scheda e leggi la fonte originale. Una priorità alta indica cosa valutare prima, non una probabilità di vendita.</p><p>Decidi se l’azienda è adatta a te, poi prepara un messaggio dalla sezione Email.</p><p>Aggiorna stato e risposte ricevute per ritrovare ogni contatto in Trattative.</p></div></details>`}
else if(['all','agencies','direct'].includes(view)||S.engines[view]){const descriptions={all:'La raccolta completa, con una sola scheda per sito.',agencies:'Agenzie e partner a cui proporti per collaborazioni e sviluppo.',direct:'Clienti diretti: negozi, artigiani, professionisti e altre attività a cui proporre i tuoi servizi.'};m.innerHTML=header(viewName(),descriptions[view]||S.engines[view].subtitle)+resultTabs()+filterUI()+'<div id="results-list"></div>';renderList()}
else if(view==='pipeline'){m.innerHTML=header('Le tue trattative','Trascina le schede tra le colonne per aggiornare lo stato. Puoi anche usare «Sposta in» su ogni scheda.')+`<div class="board-toolbar"><span class="small muted">Scorri le colonne o usa le frecce. Ogni modifica viene salvata.</span><div class="actions"><button data-board-scroll="-1" aria-label="Colonne precedenti">←</button><button data-board-scroll="1" aria-label="Colonne successive">→</button></div></div><div class="board" tabindex="0" role="region" aria-label="Trattative per stato, scorrimento orizzontale">${Object.entries(S.stages).map(([k,v])=>`<section class="column" data-stage="${k}" aria-label="${esc(v)}"><h3>${v} <span class="muted">${S.items.filter(i=>!i.dismissed_at&&i.stage===k).length}</span></h3>${S.items.filter(i=>!i.dismissed_at&&i.stage===k).map(i=>card(i,true)).join('')||'<p class="small muted">Nessuna scheda</p>'}</section>`).join('')}</div>`}
else if(view==='results'){m.innerHTML=header('Esiti commerciali','Contatti, risposte e incassi: solo i risultati che hai registrato.')+metrics()+`<div class="notice">${esc(S.stats.recommendation)}</div><details class="panel metric-details"><summary>Dettaglio per motore e storico</summary><div class="scroll" tabindex="0" role="region" aria-label="Tabella scorrevole"><table><thead><tr>${['Motore','Trovate','Valutate nel CRM','Contatti','Risposte','Conversazioni','Preventivi','Accettati','Clienti','Contratti','Incassi','Risposte %','Clienti %'].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${S.stats.engines.map(e=>`<tr><td>${badge(e.engine)} ${esc(S.engines[e.engine].name)}</td>${['found','qualified','contacted','replied','conversations','proposals','accepted','customers'].map(k=>`<td>${e[k]}</td>`).join('')}<td>${money(e.contract_value)}</td><td>${money(e.revenue)}</td><td>${e.reply_rate??'—'}</td><td>${e.win_rate??'—'}</td></tr>`).join('')}</tbody></table></div></details><p class="small muted">${esc(S.stats.attribution)} Percentuali solo da ${S.stats.minimum_sample} contatti registrati; numeratore limitato alla stessa coorte. I passaggi non registrati restano sconosciuti.</p><details class="panel"><summary>Come valutare i risultati nel tempo</summary><p class="muted">Usa gli stessi criteri di qualifica per ogni motore. Registra le conversazioni utili e gli esiti, inclusi i rifiuti. A fine periodo confronta anche tempo investito e dimensione dei campioni. Il sistema non attribuisce causalità e non promette risultati.</p></details>`}
else if(view==='settings')settingsView();else if(view==='activity')activityView();else if(view==='archive')archiveView()}
function renderList(){const items=filtered();$('#results-list').innerHTML=`<div class="sectionhead"><span class="muted small">${items.length} schede · ${new Set(items.map(i=>i.company_id)).size} contatti</span><button class="quiet" data-action="clear-filters">Azzera filtri</button></div>`+(items.length?`<div class="cards">${items.map(i=>card(i)).join('')}</div>`:empty(view==='direct'?'Nessun cliente diretto in questa vista':view==='agencies'?'Nessuna agenzia in questa vista':undefined,'Avvia una ricerca o modifica i filtri. Puoi correggere la categoria di una scheda in Stato e note.'))}
async function activityView(){const m=$('#main');m.innerHTML=header('Fonti, verifiche, attività','La traccia completa: risultati trovati, pagine escluse, verifiche riuscite e limiti dei provider.')+'<div id="history-content" class="loading">Caricamento attività…</div>';const history=await api('/history');if(view!=='activity')return;$('#history-content').className='';$('#history-content').innerHTML=`<details class="panel"><summary>Come vengono raccolte e verificate le fonti</summary><p class="muted">SearXNG scopre gli URL gratuitamente. Il sito originale viene letto separatamente rispettando robots.txt. Le date provengono dalla pagina, non dal frammento del motore di ricerca. RSS è configurabile per feed autorizzati. LinkedIn, Upwork e altre piattaforme con accesso soggetto a condizioni non vengono raccolte automaticamente.</p><p class="small muted">Lighthouse viene eseguito localmente. Un test fallito resta un limite dichiarato; non produce un punteggio inventato.</p></details>`+(history.map(r=>`<details class="panel"><summary>${badge(r.engine)} ${esc(S.engines[r.engine].name)} · ${dt(r.started_at)} · ${esc(({completed:'Completata',partial:'Completata con limiti',stopped:'Interrotta',error:'Errore',running:'In corso'})[r.status]||r.status)} — ${r.stats.added||0} nuove schede / ${r.stats.checked||0} controlli</summary>${r.items.map(i=>`<div class="statusline"><span class="tag ${i.disposition==='accepted'?'request':i.disposition==='error'?'limitation':''}">${esc(({accepted:'Inclusa',rejected:'Esclusa',duplicate:'Già presente',error:'Errore',skipped:'Saltata',info:'Informazione',found:'Trovata'})[i.disposition]||i.disposition)}</span> ${esc(i.reason)}${i.url?'<br>'+link(i.url,i.url):''}${i.query?'<br><span class="muted">Query: '+esc(i.query)+'</span>':''}</div>`).join('')}</details>`).join('')||empty('Ancora nessuna ricerca registrata','Ogni esecuzione comparirà qui con i relativi controlli.'))}
async function archiveView(){
 $('#main').innerHTML=header('Archivio precedente','Dati originali conservati. Non vengono promossi automaticamente a nuove opportunità.')+`<div class="archive-search filter-box"><label>Cerca nell’archivio<input id="archive-search" type="search" value="${esc(archiveSearch)}" placeholder="Azienda, sito o titolo"></label></div><div id="legacy-list" class="loading" role="status">Caricamento archivio…</div>`;
 try{const rows=await api('/legacy');if(view!=='archive')return;archiveRows=rows;renderArchive()}
 catch(e){if(view==='archive')$('#legacy-list').innerHTML=`<div class="notice" role="alert">${esc(e.message)} <button data-view="archive">Riprova</button></div>`}
}
function renderArchive(){
 const rows=archiveRows.filter(r=>JSON.stringify(r.data).toLocaleLowerCase('it').includes(archiveSearch.toLocaleLowerCase('it')));
 archiveOffset=Math.min(archiveOffset,Math.max(0,Math.floor((rows.length-1)/25)*25));
 $('#legacy-list').className='';
 $('#legacy-list').innerHTML=`<div class="sectionhead"><p class="small muted">${rows.length} record conservati</p></div>`+(rows.length?`<div class="panel scroll" tabindex="0" role="region" aria-label="Archivio, tabella scorrevole"><table><thead><tr><th>Record</th><th>Azienda / titolo</th><th>Stato originale</th><th>Dettagli conservati</th></tr></thead><tbody>${rows.slice(archiveOffset,archiveOffset+25).map(r=>`<tr><td>${esc(r.kind)} #${r.id}</td><td class="wrap">${esc(r.data.company_name||r.data.name||r.data.title||r.data.domain||r.data.url)}</td><td>${esc(r.data.status||'—')}</td><td><details><summary>Apri dati originali</summary><pre>${esc(JSON.stringify(r.data,null,2))}</pre></details></td></tr>`).join('')}</tbody></table></div><div class="actions pager"><button data-archive-page="-1" ${archiveOffset?'':'disabled'}>← Precedenti</button><span>${archiveOffset+1}–${Math.min(archiveOffset+25,rows.length)} di ${rows.length}</span><button data-archive-page="1" ${archiveOffset+25>=rows.length?'disabled':''}>Successive →</button></div>`:'<div class="empty"><h3>Nessun record trovato</h3><p>Prova con un altro nome o sito.</p></div>');
}

function settingsView(){const c=S.settings;$('#main').innerHTML=header('Impostazioni','Gestisci il tuo profilo, le aree di ricerca e i limiti dei servizi.')+`<form id="settings-form" class="stack"><section class="panel"><h2>Profilo e portfolio</h2><div class="grid2"><label>Nome<input name="name" value="${esc(c.name)}" required></label><label>Località<input name="location" value="${esc(c.location)}"></label><label>Portfolio<input name="portfolio" type="url" value="${esc(c.portfolio)}"></label><label>Modello Ollama locale (facoltativo)<input name="ollama_model" value="${esc(c.ollama_model)}" placeholder="Nome di un modello già installato"></label></div><p class="small muted">Senza un modello configurato, dossier e bozze usano regole locali esplicite. Nessun servizio AI a pagamento viene attivato.</p></section><details class="panel"><summary>Ricerca e limiti dei servizi</summary><div class="spacer"></div><div class="grid2"><div><strong>Ricerca gratuita · SearXNG</strong><p class="small muted">${S.providers.searxng?'Servizio locale configurato':'Servizio locale da configurare'}. Tavily disattivato.</p><input type="hidden" name="provider" value="searxng"></div><label>Intervallo di ricerca<select name="time_range">${options([['','Qualsiasi data'],['week','Ultima settimana'],['month','Ultimo mese'],['year','Ultimo anno']],c.time_range,'Seleziona')}</select></label>${[['queries_per_engine','Query per motore',1,6],['results_per_query','Risultati per query',1,20],['technical_limit','Siti per sessione Lighthouse',1,10],['minimum_sample','Contatti minimi per percentuali',5,100],['min_priority','Priorità minima shortlist',0,100],['minimum_budget','Budget minimo, se dichiarato (€)',0,100000]].map(([k,l,min,max])=>`<label>${l}<input name="${k}" type="number" min="${min}" max="${max}" value="${c[k]}" required></label>`).join('')}</div><p class="small muted">Nessun limite globale di durata della ricerca. Le singole connessioni mantengono un timeout tecnico; gli errori restano visibili. Ricerca senza crediti API: SearXNG. Richieste effettuate oggi: ${S.usage.today.searxng||0}.</p></details><section class="panel"><h2>Target commerciale</h2><p class="small muted">Escluse le S.p.A. identificate nelle fonti aziendali e le reti strutturate: almeno 10 sedi/negozi dichiarati, almeno 250 dipendenti dichiarati o un gruppo multinazionale dichiarato. Queste sono soglie di selezione, non una classificazione legale. I filtri valgono per tutti i motori, anche con problemi Lighthouse.</p><h2>Area geografica</h2><p class="small muted">Preferenza per Veneto, Lombardia, Piemonte e Toscana. Le esclusioni si applicano alle località dichiarate nelle fonti; una località sconosciuta resta da verificare.</p><div class="grid2"><label>Località prioritarie · una per riga<textarea name="preferred_locations">${esc(c.preferred_locations.join('\n'))}</textarea></label><label>Località escluse · una per riga<textarea name="excluded_locations">${esc(c.excluded_locations.join('\n'))}</textarea></label></div><details><summary>Ricerche personalizzate e feed RSS</summary><p class="muted small">Una query per riga. Il motore E incrocia i dati raccolti e non usa ricerche esterne.</p><div class="grid2">${Object.entries(c.queries).map(([k,q])=>`<label>${k} · ${esc(S.engines[k].name)}<textarea name="queries_${k}">${esc(q.join('\n'))}</textarea></label>`).join('')}</div><div class="spacer"></div><label>Feed RSS autorizzati · un URL HTTPS per riga<textarea name="rss_feeds">${esc(c.rss_feeds.join('\n'))}</textarea></label></details></section><div class="actions"><button class="primary" type="submit">Salva impostazioni</button><button type="button" data-action="backup">Crea backup verificato</button></div></form>`}
function researchDialog(){const d=$('#research');d.innerHTML=`<form id="research-form"><div class="dialoghead"><div><h2 id="research-title">Cerca nuovi contatti</h2><p class="muted small">Scegli quali motori attivare. Puoi interromperli in qualsiasi momento.</p></div><button type="button" class="quiet" data-close="research" aria-label="Chiudi">✕</button></div><div class="dialogbody stack">${Object.entries(S.engines).map(([k,v])=>`<label class="check engine-option"><input type="checkbox" name="engine" value="${k}" checked>${badge(k)}<span>${esc(engineNames[k])}<small>${esc(v.subtitle)}</small></span></label>`).join('')}<details><summary>Controlla URL specifici</summary><label>Una pagina originale per riga · massimo 20<textarea name="urls" placeholder="https://azienda.it/lavora-con-noi/"></textarea></label><p class="small muted">Se inserisci URL, i motori selezionati verificano queste pagine senza eseguire query. E collega comunque i segnali già raccolti.</p></details><div class="notice small">Ricerca gratuita con SearXNG. Fino a ${S.settings.queries_per_engine} query per motore di ricerca. D esamina fino a ${S.settings.technical_limit} siti con Lighthouse. Nessuna email viene inviata.</div><button class="primary" type="submit" ${S.job.running?'disabled':''}>${S.job.running?'Ricerca già in corso':'Avvia i motori selezionati'}</button></div></form>`;d.showModal()}
async function openDetail(id){const seq=++detailSequence;const item=await api('/prospects/'+id);if(seq!==detailSequence)return;current=item;tab='summary';renderDetail();showDetail()}
function renderDetail(){if($('#detail').contains(toastElement))document.body.append(toastElement);const i=current;$('#detail').innerHTML=`<div class="dialoghead"><div><div class="tags">${badge(i.engine)}<span class="tag">${esc(S.stages[i.stage])}</span><span class="tag">Priorità ${i.score}/100</span></div><div class="spacer"></div><h2 id="detail-title">${esc(i.name)}</h2>${link(i.website,i.domain)}</div><button class="quiet" data-close="detail" aria-label="Chiudi scheda">✕</button></div><div class="dialogbody"><div class="contact-banner ${isContacted(i)?'is-contacted':''}">${contactControl(i)}${dismissalControl(i)}</div>${i.target_exclusion?`<div class="notice"><strong>${i.dismissed_at?'Proposta eliminata da te':'Esclusa dal target'}</strong><p>${esc(i.target_exclusion.reason)}</p>${i.dismissed_at?'Il sito resta escluso finché non ripristini la proposta.':link(i.target_exclusion.url,'Fonte della verifica')}</div>`:''}<nav class="tabs">${[['summary','In breve'],['evidence','Fonti'],['audit','Controlli del sito'],['draft','Email'],['manage','Stato e note']].map(([k,t])=>`<button data-tab="${k}" class="${tab===k?'active':''}" ${tab===k?'aria-current="page"':''}>${t}</button>`).join('')}</nav><div id="detail-content"></div></div>`;const p=$('#detail-content');if(tab==='summary'){const ev=primaryEvidence(i);p.innerHTML=`<section class="summary-intro"><p class="small"><strong>${esc(groupLabels[i.contact_group])}</strong><br>${esc(i.contact_group_basis)} ${i.contact_group_url?link(i.contact_group_url,'Fonte'):''}</p><p class="reason"><strong>Perché te la propongo</strong>${esc(i.reason)}</p><div class="summary-source"><span class="tag ${ev?.kind||'fact'}">${esc(kinds[ev?.kind]||'Riscontro')}</span><div class="spacer"></div>${ev?link(ev.url,ev.source_title||'Leggi la fonte originale'):''}<p class="source-meta">${ev?.published_at?'Pubblicata il '+dt(ev.published_at):'Data di pubblicazione non disponibile: verifica che il contenuto sia ancora attuale.'}${ev?.checked_at?' · Controllata il '+dt(ev.checked_at):''}</p></div></section><div class="grid2 summary-grid"><section class="panel"><h3>Servizio da proporre</h3><p>${esc(i.service)}</p><div class="spacer"></div><span class="small muted">Proposta da valutare in base alle esigenze reali.</span></section><section class="panel"><h3>Prossimo passo</h3><p>${esc(nextStep(i))}</p><div class="spacer"></div><button data-tab="evidence">Controlla le fonti →</button></section></div><details class="helper"><summary>Cosa manca da verificare</summary>${i.missing.map(v=>`<p>${esc(v)}</p>`).join('')||'<p>Nessun punto aggiuntivo registrato.</p>'}</details><div class="notice"><strong>Ipotesi da confermare</strong><p>${esc(i.hypothesis)}</p></div><div class="actions"><button data-tab="manage">Aggiorna stato e note</button><button data-tab="draft">Prepara un’email</button></div><p class="small muted helper">Priorità ${i.score}/100: aiuta a ordinare le aziende da valutare, non indica la probabilità di risposta.</p>`}else if(tab==='evidence')p.innerHTML=`<div class="notice"><span class="tag hypothesis">Ipotesi commerciale</span><p>${esc(i.hypothesis)}</p><span class="small">Questo passaggio interpreta i fatti: non dimostra budget o intenzione d’acquisto.</span></div>${i.evidence.map(e=>`<article class="evidence"><div class="tags"><span class="tag ${e.kind}">${esc(kinds[e.kind]||e.kind)}</span>${badge(e.engine)}</div><h3>${esc(e.label)}</h3><p>${esc(e.detail)}</p><div class="source-link">${link(e.url,e.source_title||e.url)}</div><div class="source-meta">Pubblicato: ${dt(e.published_at)} · Controllato: ${dt(e.checked_at)}<details><summary>Dettagli della fonte</summary>URL originale: ${esc(e.url)}<br>Scoperta: ${esc(e.provider)} · Tipo: ${esc(e.source_type)}${e.metadata.date_origin?' · Data da '+esc(e.metadata.date_origin):''}</details></div></article>`).join('')}<div class="grid2"><section class="panel"><details><summary>Come viene calcolata la priorità</summary>${Object.entries(i.score_detail).map(([k,v])=>`<div class="scoreline"><span>${esc(k)}</span><b>${v>0?'+':''}${v}</b></div>`).join('')}<p class="small muted">${esc(i.priority_cap||'Eventuali soglie e limiti del motore si applicano dopo la somma.')} Priorità operativa, non probabilità di risposta.</p></details></section><section class="panel"><h2>Da verificare</h2>${i.missing.map(v=>`<p class="small muted">• ${esc(v)}</p>`).join('')}<h3>Contatti pubblici</h3>${i.contacts.map(c=>`<p>${esc(c.value)}<br><span class="small muted">${esc(c.basis)}</span><br>${link(c.url,'Fonte del contatto')}</p>`).join('')||'<p class="muted small">Nessun contatto verificato.</p>'}${i.prior_contacted?'<div class="notice">Azienda già contattata nella versione precedente.</div>':''}</section></div>`;
else if(tab==='audit'){const a=i.audit;p.innerHTML=`<div class="actions"><button data-action="audit" ${S.job.running?'disabled':''}>Esegui Lighthouse e controlli</button><span class="small muted">Homepage · mobile + desktop · nessun invio di moduli</span></div><div class="spacer"></div>`+(a?`${(a.pagespeed||[]).map(r=>`<section class="panel"><h2>Lighthouse · ${esc(r.strategy)}</h2>${r.status==='ok'?`<div class="scoretiles">${Object.entries(r.scores||{}).map(([k,v])=>`<div class="scoretile"><b>${v??'—'}</b><span>${esc(({performance:'Prestazioni',accessibility:'Accessibilità','best-practices':'Buone pratiche',seo:'SEO'})[k]||k)}</span></div>`).join('')}</div><p class="small muted">Misurato: ${dt(r.fetch_time)} · Test di laboratorio, variabile fra esecuzioni.</p>${r.report_url?link(r.report_url,'Report originale JSON'):''}`:`<p class="muted">${esc(r.message||'Test non disponibile')}</p>`}</section>`).join('')}<section class="panel"><h2>SEO / GEO / AEO</h2><p class="small muted">Riscontri sull’HTML e dati strutturati. Nessun punteggio universale di visibilità nei motori generativi è deducibile da questi controlli.</p>${(a.seo?.checks||[]).map(c=>`<div class="statusline"><span class="tag ${c.status==='presente'?'fact':'limitation'}">${esc(c.status)}</span> <b>${esc(c.label)}</b><p>${esc(c.detail)}</p></div>`).join('')}<div class="spacer"></div>${(a.seo?.geo_aeo?.content_checks||[]).map(c=>`<p class="small">${c.present?'✓':'—'} ${esc(c.label)}</p>`).join('')}<p class="small muted">Dati strutturati dichiarati: ${esc((a.seo?.geo_aeo?.structured_types||[]).join(', ')||'nessuno rilevato')}. ${esc(a.seo?.geo_aeo?.note||'')}</p></section>${(a.limitations||[]).map(l=>`<p class="small muted">• ${esc(l)}</p>`).join('')}`:'<div class="empty"><h2>Nessun controllo disponibile</h2><p>Avvia il controllo per misurare questo sito. I risultati arriveranno al termine della sessione.</p></div>')}
else if(tab==='draft'){const d=i.draft||{};p.innerHTML=`<div class="notice small">Bozza basata sui riscontri del dossier. Rileggi destinatario e testo. L’app apre Gmail solo dopo la tua conferma e non invia messaggi.</div><button data-action="generate-draft" ${i.do_not_contact?'disabled':''}>${d.email?'Rigenera bozza':'Prepara bozza dalle fonti'}</button><div class="spacer"></div>${d.email?`<form id="draft-form" class="stack draft"><label>Oggetto<input name="subject" value="${esc(d.subject)}" required></label><label>Email<textarea name="email" required>${esc(d.email)}</textarea></label><details><summary>Traccia proposta e follow-up</summary><label>Proposta<textarea class="secondary-text" name="proposal">${esc(d.proposal)}</textarea></label><label>Follow-up<textarea class="secondary-text" name="followup">${esc(d.followup)}</textarea></label></details><button type="submit">Salva le modifiche alla bozza</button></form><div class="spacer"></div><div class="panel stack"><label>Destinatario<input id="recipient" type="email" value="${esc(i.contacts.find(c=>c.type==='email')?.value||'')}" placeholder="Email verificata"></label><p class="small muted">Presupposto registrato: ${esc(i.contact_basis||'mancante — impostalo in Stato e note')}. Un indirizzo pubblico non equivale al consenso.</p><label class="check"><input id="compose-confirm" type="checkbox">Ho verificato testo, destinatario e presupposto del contatto.</label><button class="primary" data-action="compose" ${i.do_not_contact?'disabled':''}>Apri la bozza in Gmail ↗</button><div id="compose-link"></div></div>`:''}`}
else if(tab==='manage')p.innerHTML=`<form id="manage-form" class="stack"><label>Categoria del contatto<select name="contact_group">${options(Object.entries(groupLabels),i.contact_group,'Seleziona categoria')}</select></label><p class="small muted">${esc(i.contact_group_basis)} ${i.contact_group_url?link(i.contact_group_url,'Fonte della classificazione'):''}</p><div class="grid2"><label>Stato<select name="stage">${options(Object.entries(S.stages),i.stage,'Seleziona')}</select></label><label>Presupposto del contatto<select name="contact_basis">${options([['request','Risposta a richiesta esplicita'],['consent','Consenso documentato'],['existing_relationship','Rapporto esistente, da verificare'],['other_documented','Altro presupposto documentato']],i.contact_basis,'Non ancora verificato')}</select></label><label>Valore contratto (€)<input name="contract_value" type="number" min="0" step="0.01" value="${i.contract_value??''}"></label><label>Incassato (€)<input name="paid_value" type="number" min="0" step="0.01" value="${i.paid_value||0}"></label></div><label>Note e documentazione<textarea name="notes">${esc(i.notes)}</textarea></label><label>Nuova interazione<textarea name="interaction" placeholder="Esito della telefonata, risposta ricevuta…"></textarea></label><label class="check"><input name="conversation" type="checkbox">Questa interazione è una conversazione commerciale utile</label><label class="check"><input name="do_not_contact" type="checkbox" ${i.do_not_contact?'checked':''}>Non contattare questa azienda</label><button class="primary" type="submit">Salva stato e note</button></form><div class="spacer"></div><h3>Storico</h3>${i.interactions.map(e=>`<div class="statusline"><span class="muted">${dt(e.created_at)}</span> · ${esc(e.detail)}</div>`).join('')||'<p class="muted">Nessuna interazione registrata.</p>'}${(i.previous_records||[]).some(r=>r.notes||r.contract_value||r.paid_value||r.draft!=='{}')?`<details class="helper"><summary>Note, importi e bozze delle schede riunite</summary>${i.previous_records.filter(r=>r.notes||r.contract_value||r.paid_value||r.draft!=='{}').map(r=>`<section class="panel"><h3>Scheda originale #${r.id} · ${esc(engineNames[r.engine])}</h3><p>${esc(r.notes||'Nessuna nota')}</p><p>Contratto: ${money(r.contract_value)} · Incassato: ${money(r.paid_value)}</p>${r.draft!=='{}'?`<pre>${esc(JSON.stringify(JSON.parse(r.draft),null,2))}</pre>`:''}</section>`).join('')}</details>`:''}`}
async function refresh(){S=await api('/state');render()}
async function updateDetail(){current=await api('/prospects/'+current.id);renderDetail();S=await api('/state');render()}
document.addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b)return;try{if(b.dataset.view){navigate(b.dataset.view);return}if(b.dataset.boardScroll){$('.board')?.scrollBy({left:Number(b.dataset.boardScroll)*330,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return}if(b.dataset.archivePage){archiveOffset+=Number(b.dataset.archivePage)*25;renderArchive();$('#archive-search').scrollIntoView({block:'center'});return}if(b.dataset.open){detailOpener={kind:'data-open',value:b.dataset.open};await openDetail(b.dataset.open);return}if(b.dataset.close){$('#'+b.dataset.close).close();return}if(b.dataset.tab){tab=b.dataset.tab;renderDetail();$('.tabs [data-tab="'+tab+'"]').focus({preventScroll:true});return}const a=b.dataset.action;if(!a)return;if(a==='retry-app'){await refresh();return}if(a==='research'){await researchDialog();return}if(a==='clear-filters'){filters={};renderMain();return}if(a==='dismiss-proposal'||a==='restore-proposal'){await saveDismissal(Number(b.dataset.id),a==='dismiss-proposal');return}if(a==='confirm-contact'){await saveStage(Number(b.dataset.id),'contacted',true);return}b.disabled=true;if(a==='stop'){await api('/research/stop',{});toast('Interruzione richiesta: i dati già raccolti restano salvati.')}
if(a==='backup'){const r=await api('/backup',{});toast('Backup verificato: '+r.path)}
if(a==='audit'){await api('/prospects/'+current.id+'/audit',{});toast('Audit avviato. I risultati saranno visibili al termine.');await refresh()}
if(a==='generate-draft'){await api('/prospects/'+current.id+'/draft',{});await updateDetail()}
if(a==='compose'){const r=await api('/prospects/'+current.id+'/compose',{recipient:$('#recipient').value,confirmed:$('#compose-confirm').checked});$('#compose-link').innerHTML=link(r.url,'Apri Gmail con questa bozza');window.open(r.url,'_blank','noopener,noreferrer')}
} catch(e){toast(e.message)}finally{b.disabled=false}});
document.addEventListener('input',ev=>{if(ev.target.id==='archive-search'){archiveSearch=ev.target.value;archiveOffset=0;renderArchive();return}const k=ev.target.dataset.filter;if(k){filters[k]=ev.target.value;renderList()}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.target,data=new FormData(f),button=f.querySelector('[type=submit]');if(button)button.disabled=true;try{if(f.id==='research-form'){const engines=data.getAll('engine');if(!engines.length)throw new Error('Seleziona almeno un motore');await api('/research',{engines,urls:String(data.get('urls')||'').split('\n').map(s=>s.trim()).filter(Boolean)});$('#research').close();await refresh()}
if(f.id==='settings-form'){const v=Object.fromEntries(data);for(const k of ['queries_per_engine','results_per_query','technical_limit','minimum_sample','min_priority','minimum_budget','daily_api_limit','monthly_api_limit'])if(k in v)v[k]=['daily_api_limit','monthly_api_limit'].includes(k)&&v[k].trim()===''?null:Number(v[k]);for(const k of ['preferred_locations','excluded_locations'])v[k]=v[k].split('\n').map(s=>s.trim()).filter(Boolean);if('queries_A' in v){v.queries={};for(const k of ['A','B','C','D']){v.queries[k]=v['queries_'+k].split('\n').map(s=>s.trim()).filter(Boolean);delete v['queries_'+k]}}v.rss_feeds=v.rss_feeds.split('\n').map(s=>s.trim()).filter(Boolean);await api('/settings',v);await refresh();toast('Impostazioni salvate')}
if(f.id==='draft-form'){await api('/prospects/'+current.id+'/draft',{draft:{...current.draft,...Object.fromEntries(data)}});await updateDetail();toast('Bozza salvata')}
if(f.id==='manage-form'){const v=Object.fromEntries(data);v.contract_value=v.contract_value===''?null:Number(v.contract_value);v.paid_value=Number(v.paid_value);v.conversation=data.has('conversation');v.do_not_contact=data.has('do_not_contact');await api('/prospects/'+current.id+'/update',v);await updateDetail();toast('Scheda aggiornata')}
}catch(e){toast(e.message)}finally{if(button)button.disabled=false}});
refresh().catch(e=>{$('#app').innerHTML=`<main class="startup-error panel"><span class="eyebrow">CustomerSearch</span><h1>Impossibile caricare lo spazio di lavoro</h1><p class="muted">${esc(e.message)}</p><button class="primary" data-action="retry-app">Riprova</button></main>`});
async function pollState(){
 if(!S||pollBusy)return;pollBusy=true;
 try{
  const before=S,next=await api('/state');S=next;connectionStatus();
  if(typeof updateResearchState==='function')updateResearchState(before);
  // Keep forms, open dossiers and dragged cards stable while background work progresses.
  const idle=!document.activeElement?.matches('input,textarea,select,button,summary')&&!stageSaving&&!dragState&&!$('#detail').open&&!$('#research').open;
  if(idle&&['legacy','pipeline','results'].includes(view)&&JSON.stringify(before.items)!==JSON.stringify(next.items)){
   const left=$('.board')?.scrollLeft||0;renderMain();if($('.board'))$('.board').scrollLeft=left;
  }
 }catch{connectionStatus(true)}finally{pollBusy=false}
}
setInterval(pollState,3000);

// One persistence path for the contact button, board drop and keyboard select.
async function saveStage(id,stage,confirmContact=false){
  if(stageSaving)return;
  const item=S.items.find(i=>i.id===id);
  if(!item||!S.stages[stage]||(!confirmContact&&item.stage===stage))return;
  if(confirmContact&&isContacted(item))return;
  if(stage==='won'&&!item.contract_value){
    await openDetail(id);tab='manage';renderDetail();
    $('#manage-form [name=stage]').value='won';
    $('#manage-form [name=contract_value]').focus();
    toast('Inserisci il valore del contratto e salva per segnare il cliente come acquisito.');
    return;
  }
  const boardScroll=$('.board')?.scrollLeft||0;
  stageSaving=true;
  document.querySelectorAll('[data-action="confirm-contact"], [data-move-id]').forEach(el=>el.disabled=true);
  try{
    const body={stage};
    if(confirmContact)body.interaction='Contatto confermato manualmente.';
    const updated=await api('/prospects/'+id+'/update',body);
    // Keep the successful result locally even if the following refresh fails.
    S.items=S.items.map(i=>i.id===id?updated:i);
    S=await api('/state');
    if($('#detail').open){const position=$('#detail').scrollTop;if(current){current=await api('/prospects/'+current.id);renderDetail()}else if(typeof researchOpportunity!=='undefined'&&researchOpportunity){await researchDetail(researchOpportunity.id)}$('#detail').scrollTop=position}
    toast(confirmContact?'Contatto confermato. La scheda è ora verde.':'Spostata in «'+S.stages[stage]+'».');
  }catch(e){toast(e.message)}
  finally{
    stageSaving=false;renderMain();
    if($('.board'))$('.board').scrollLeft=boardScroll;
    document.querySelectorAll('[data-action="confirm-contact"], [data-action="dismiss-proposal"], [data-action="restore-proposal"], [data-move-id]').forEach(el=>el.disabled=false);
  }
}
document.addEventListener('change',async ev=>{
  if(!ev.target.matches('[data-move-id]'))return;
  const id=Number(ev.target.dataset.moveId),stage=ev.target.value;
  ev.target.value=S.items.find(i=>i.id===id)?.stage||'';
  try{await saveStage(id,stage)}catch(e){toast(e.message)}
});

let dragState=null,dragFrame=0;
function highlightDrop(x,y){
  const column=document.elementFromPoint(x,y)?.closest('.column[data-stage]');
  document.querySelectorAll('.column.drop-target').forEach(el=>{if(el!==column)el.classList.remove('drop-target')});
  if(column)column.classList.add('drop-target');
  return column;
}
function dragScroll(){
  if(!dragState)return;
  const board=$('.board');
  if(board){
    const r=board.getBoundingClientRect(),x=dragState.x,y=dragState.y;
    if(y>=r.top&&y<=Math.min(r.bottom,innerHeight)){
      if(x>r.right-64)board.scrollLeft+=14;
      else if(x<r.left+64)board.scrollLeft-=14;
      if(y>innerHeight-55)window.scrollBy(0,12);
      else if(y<60)window.scrollBy(0,-12);
    }
    const column=highlightDrop(x,y);
    if(column){const cr=column.getBoundingClientRect();if(y>Math.min(cr.bottom,innerHeight)-55)column.scrollTop+=12;else if(y<cr.top+65)column.scrollTop-=12;}
  }
  dragFrame=requestAnimationFrame(dragScroll);
}
function beginDrag(card,ev,mode){
  if(stageSaving||dragState)return false;
  dragState={id:Number(card.dataset.cardId),x:ev.clientX,y:ev.clientY,mode};
  card.classList.add('dragging');document.body.classList.add('board-dragging');
  dragFrame=requestAnimationFrame(dragScroll);return true;
}
function endDrag(){
  cancelAnimationFrame(dragFrame);dragState=null;
  document.body.classList.remove('board-dragging');
  document.querySelectorAll('.dragging,.drop-target').forEach(el=>el.classList.remove('dragging','drop-target'));
}
document.addEventListener('dragstart',ev=>{
  const card=ev.target.closest('.board .card');
  if(!card)return;
  if(ev.target.closest('a,button,select,input')||!beginDrag(card,ev,'native')){ev.preventDefault();return}
  ev.dataTransfer.effectAllowed='move';ev.dataTransfer.setData('text/plain',card.dataset.cardId);
});
document.addEventListener('dragover',ev=>{
  if(!dragState||dragState.mode!=='native')return;
  ev.preventDefault();ev.dataTransfer.dropEffect='move';
  dragState.x=ev.clientX;dragState.y=ev.clientY;highlightDrop(ev.clientX,ev.clientY);
});
document.addEventListener('drop',async ev=>{
  if(!dragState||dragState.mode!=='native')return;
  ev.preventDefault();const id=dragState.id,column=ev.target.closest('.column[data-stage]');endDrag();
  if(column)try{await saveStage(id,column.dataset.stage)}catch(e){toast(e.message)}
});
document.addEventListener('dragend',endDrag);
// Touch/pen use the dedicated grip so ordinary scrolling and card controls stay usable.
document.addEventListener('pointerdown',ev=>{
  if(ev.pointerType==='mouse'||!ev.isPrimary)return;
  const grip=ev.target.closest('.drag-grip');if(!grip)return;
  if(beginDrag(grip.closest('.card'),ev,'touch')){ev.preventDefault();grip.setPointerCapture(ev.pointerId)}
});
document.addEventListener('pointermove',ev=>{
  if(!dragState||dragState.mode!=='touch')return;
  dragState.x=ev.clientX;dragState.y=ev.clientY;highlightDrop(ev.clientX,ev.clientY);
});
document.addEventListener('pointerup',async ev=>{
  if(!dragState||dragState.mode!=='touch')return;
  const id=dragState.id,column=highlightDrop(ev.clientX,ev.clientY);endDrag();
  if(column)try{await saveStage(id,column.dataset.stage)}catch(e){toast(e.message)}
});
document.addEventListener('pointercancel',()=>{if(dragState?.mode==='touch')endDrag()});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape')endDrag()});

async function saveDismissal(id,dismissed){
  if(stageSaving)return;
  stageSaving=true;
  document.querySelectorAll('[data-action="dismiss-proposal"],[data-action="restore-proposal"]').forEach(el=>el.disabled=true);
  const scroll=$('.board')?.scrollLeft||0;
  try{
    const item=await api('/prospects/'+id+(dismissed?'/dismiss':'/restore'),{});
    S.items=S.items.map(i=>i.company_id===item.company_id?item:i);
    if($('#detail').open&&(current?.company_id===item.company_id||(typeof researchOpportunity!=='undefined'&&researchOpportunity?.company_id===item.company_id)))$('#detail').close();
    S=await api('/state');
    toast(dismissed?'Proposta eliminata: questo sito non verrà riproposto. La ritrovi in Contatti → Elenco → Eliminate da me.':'Proposta ripristinata.');
  }catch(e){toast(e.message)}
  finally{
    stageSaving=false;render();
    if($('.board'))$('.board').scrollLeft=scroll;
    document.querySelectorAll('[data-action="dismiss-proposal"],[data-action="restore-proposal"]').forEach(el=>el.disabled=false);
  }
}
